            majmaAlBayanOverview = "في «مجمع البيان في تفسير القرآن» لأمين الإسلام الشيخ أبي علي الفضل بن الحسن الطبرسي: سورة البقرة مدنية نزلت في مدد شتى، وهي سنام القرآن ومشتملة على أصول العقائد والشرائع وأحكام الأموال والقصاص والجهاد والنكاح والطلاق وحجة البيت، وفيها سيدة آي القرآن وهي (آية الكرسي) التي تضمنت أعظم براهين التوحيد، وخواتيمها العظيمة التي جاء في فضلها أنها كنز من تحت العرش. وافتتحت بتقرير إعجاز الكتاب وهدايته للمتقين وبيان صفات المؤمنين والكافرين والمنافقين.",
