                    ),
                    tafsir = "لا يلزم الله نفساً بما يشق عليها ويفوق طاقتها، لها ثواب ما عملت من خير وعليها وزر ما ارتكبت من شر. ربنا لا تعاقبنا إن نسينا أو أخطأنا في شيء بغير تعمد، ربنا ولا تكلفنا من الأعمال الشاقة ما كلفته على الأمم قبلنا بذنوبهم، ربنا ولا تحمّلنا ما لا طاقة لنا بحمله من البلايا والشدائد، وتجاوز عن ذنوبنا واسترها وارحمنا بلطفك، أنت ولينا وناصرنا فانصرنا على القوم الكافرين.",
                    tafsirAlAmthal = "يختم تفسير الأمثل سورة البقرة ببيان الرحمة الإلهية العظمى في نفي الحرج والمشقة؛ فالتكاليف الشرعية متناسبة تماماً مع الفطرة والقدرة الإنسانية. ثم يأتي هذا الدعاء الإيماني الشامل الخاشع المفعم بالرجاء والاعتراف بالضعف الإنساني، فيسأل المؤمن ربه الصفح والمغفرة والتخفيف من الأثقال، ويختم بالتوكل المطلق على الله (أنت مولانا) وطلب النصر على قوى الكفر والظلم لتقوم راية العدل والتوحيد.",
                    tafsirMajmaAlBayan = "في «مجمع البيان» لأمين الإسلام الطبرسي: تقرير لقاعدة العدل الإلهي واللطف بالعباد، فالتكاليف الشرعية كلها في حدود وسع الطاقة ومقدور المكلفين لا حرج فيها؛ والوسع ما يسع الإنسان فعله دون حرج ولا مشقة بالغة. ثم لقن الله المؤمنين هذا الدعاء الرفيع طلباً للتخفيف والرحمة والنصرة، وجاء في الروايات أن الله تعالى قال عند كل دعوة منها: «قد فعلت ذلك بفضلي ورحمتي».",
                    tafsirAlMizan = "في «تفسير الميزان» للعلامة الطباطبائي: بيان قرآني تحليلي في الآية (286) يفسر القرآن بالقرآن، موضحاً دقائق التوحيد والحقائق الإيمانية والمعنوية الكامنة في النظم الإلهي البديع.",
                    englishTranslation = "Allah does not burden a soul beyond that it can bear. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. 'Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people.'"
                )
