        Surah(
            id = "003",
            number = 3,
            nameArabic = "سورة آل عمران",
            nameEnglish = "Ali 'Imran",
            versesCount = 200,
            revelationType = "مدنية",
            hasBasmalah = true,
            educationalNotes = "سورة مدنية جليلة، سميت بآل عمران لورود قصة أسرة عمران الصالحة (والد السيدة مريم عليها السلام وولادة عيسى عليه السلام). تُعنى السورة بترسيخ عقيدة التوحيد، ومحاورة أهل الكتاب بحجة العقل والمنطق، وتفصيل شأن المحكم والمتشابه، ودعاء الراسخين في العلم، وآية المباهلة (الآية 61)، وآية الاعتصام بحبل الله والوحدة الإسلامية (الآية 103)، وتثبيت المؤمنين بعد غزوة أحد، وتختم بآيات التفكر في خلق السماوات والأرض والدعاء المستجاب (الآيات 190-200). غنية بأحكام التجويد المتقدمة: المد اللازم الحرفي، أحكام النون الساكنة والتنوين والميم الساكنة، الإقلاب، الإدغام، الإخفاء الحقيقي، القلقلة، وترقيق وتفخيم الراء ولام لفظ الجلالة.",
            majmaAlBayanOverview = "في «مجمع البيان في تفسير القرآن» لأمين الإسلام الشيخ أبي علي الفضل بن الحسن الطبرسي: سورة آل عمران مدنية مئتا آية، سميت بها لما تضمنته من قصة عمران وامرأته ومريم وعيسى عليهم السلام وما أجرى الله من خوارق العادات في ولادته وحفظ أمه. وقد روى الطبرسي في فضلها عن النبي ﷺ: «من قرأ سورة آل عمران أُعطي بكل آية منها أماناً على جسر جهنم». وروي أنها والزهراء الأخرى (البقرة) تأتيان يوم القيامة كأنهما غمامتان أو غيايتان تُحاجّان عن صاحبهما. بيّن الطبرسي أن أعظم مقاصد السورة: تثبيت وحدانية الصانع جل وعلا، ودحض شبهات النصارى في شأن عيسى بن مريم عليه السلام بالمحكم من الأدلة العقلية والنقلية، وبيان الفرق بين المحكمات التي هي أصل الشريعة والمتشابهات، والنهي عن التفرق والاعتصام بحبل الله المتين.",
            alMizanOverview = "في «الميزان في تفسير القرآن» للعلامة الطباطبائي: السورة تؤصل للتوحيد الخالص وتدحض الشبهات والمغالاة، وتفصل بين المحكم والمتشابه، وتستحضر واقعة المباهلة مع نصارى نجران وولادة مريم وعيسى عليهما السلام، وتستخلص سنن النصر والتمحيص من غزوة أحد، وتدعو إلى المرابطة والصبر.",
            fullText = "الم (1) اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ (2) نَزَّلَ عَلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ التَّوْرَاةَ وَالْإِنجِيلَ (3) هُوَ الَّذِي أَنزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ مُّحْكَمَاتٌ هُنَّ أُمُّ الْكِتَابِ وَأُخَرُ مُتَشَابِهَاتٌ ۖ فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ابْتِغَاءَ الْفِتْنَةِ وَابْتِغَاءَ تَأْوِيلِهِ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُ إِلَّا اللَّهُ ۗ وَالرَّاسِخُونَ فِي الْعِلْمِ يَقُولُونَ آمَنَّا بِهِ كُلٌّ مِّنْ عِندِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّا أُولُو الْأَلْبَابِ (7) رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ (8) شَهِدَ اللَّهُ أَنَّهُ لَا إِلَٰهَ إِلَّا هُوَ وَالْمَلَائِكَةُ وَأُولُو الْعِلْمِ قَائِمًا بِالْقِسْطِ ۚ لَا إِلَٰهَ إِلَّا هُوَ الْعَزِيزُ الْحَكِيمُ (18) قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ وَتَنزِعُ الْمُلْكَ مِمَّن تَشَاءُ وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن تَشَاءُ ۖ بِيَدِكَ الْخَيْرُ ۖ إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ (26) وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا ۚ وَاذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَاءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِ إِخْوَانًا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍ مِّنَ النَّارِ فَأَنقَذَكُم مِّنْهَا ۗ كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَهْتَدُونَ (103) إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِّأُولِي الْأَلْبَابِ (190) الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ (191) يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ (200)",
            ayahs = listOf(
                Ayah(
