            nameEnglish = "An-Nisa",
            versesCount = 176,
            revelationType = "مدنية",
            hasBasmalah = true,
            educationalNotes = "سورة مدنية جليلة، تُعنى بتنظيم شؤون الأسرة والمجتمع المسلم وحماية حقوق الضعفاء واليتامى والنساء، والعدالة والأمانة، وإرساء مبادئ القضاء العادل، وإطاعة الله ورسوله وأولي الأمر (الآية 59)، والتحذير من النفاق ومحاورة أهل الكتاب في شأن عيسى بن مريم عليه السلام. غنية بأحكام التجويد المتقنة: المدود المتصلة والمنفصلة، أحكام النون الساكنة والتنوين والميم الساكنة، القلقلة، وترقيق وتفخيم اللامات والراءات.",
            majmaAlBayanOverview = "في «مجمع البيان في تفسير القرآن» لأمين الإسلام الشيخ الطبرسي: سورة النساء مدنية مئة وست وسبعون آية، روي عن أمير المؤمنين علي بن أبي طالب عليه السلام: «من قرأ سورة النساء في كل جمعة أُومِن من ضغطة القبر». وعن النبي ﷺ: «من قرأها فكأنما تصدق على كل من ورث ميراثاً، وأُعطي من الأجر كمن اشترى محرراً وبرئ من الشرك». وقد صدّرها سبحانه بالأمر بالتقوى وصلة الأرحام وحفظ أموال اليتامى وإيتاء النساء مهورهن، ثم فصّل فيها أحكام المواريث والحدود، والنهي عن أكل أموال الناس بالباطل، والأمر بأداء الأمانات إلى أهلها والحكم بالعدل، ولزوم طاعة أولي الأمر المعصومين، ومقاتلة أهل البغي ونصرة المستضعفين، وإقامة الشهادة بالقسط ولو على النفس والوالدين والأقربين.",
            alMizanOverview = "في «الميزان في تفسير القرآن» للعلامة الطباطبائي: ترسي سورة النساء دعائم المجتمع الإنساني القائم على وحدة النفس الإنسانية، وتكفل حقوق الضعفاء واليتامى والنساء، وتفصل في أحكام الإرث والأنكحة، وتوجب طاعة أولي الأمر المقرونة بطاعة الرسول ﷺ في تدبير شؤون الأمة وإقامة العدل.",
            fullText = "يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً ۚ وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ ۚ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا (1) وَآتُوا الْيَتَامَىٰ أَمْوَالَهُمْ ۖ وَلَا تَتَبَدَّلُوا الْخَبِيثَ بِالطَّيِّبِ ۖ وَلَا تَأْكُلُوا أَمْوَالَهُمْ إِلَىٰ أَمْوَالِكُمْ ۚ إِنَّهُ كَانَ حُوبًا كَبِيرًا (2) يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ إِلَّا أَن تَكُونَ تِجَارَةً عَن تَرَاضٍ مِّنكُمْ ۚ وَلَا تَقْتُلُوا أَنفُسَكُمْ ۚ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا (29) وَاعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا ۖ وَبِالْوَالِدَيْنِ إِحْسَانًا وَبِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَالْجَارِ ذِي الْقُرْبَىٰ وَالْجَارِ الْجُنُبِ وَالصَّاحِبِ بِالْجَنبِ وَابْنِ السَّبِيلِ وَمَا مَلَكَتْ أَيْمَانُكُمْ ۗ إِنَّ اللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًا فَخُورًا (36) إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا الْأَمَانَاتِ إِلَىٰ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ النَّاسِ أَن تَحْكُمُوا بِالْعَدْلِ ۚ إِنَّ اللَّهَ نِعِمَّا يَعِظُكُم بِهِ ۗ إِنَّ اللَّهَ كَانَ سَمِيعًا بَصِيرًا (58) يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنكُمْ ۖ فَإِن تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۚ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا (59) وَمَن يُطِعِ اللَّهَ وَالرَّسُولَ فَأُولَٰئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِم مِّنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ ۚ وَحَسُنَ أُولَٰئِكَ رَفِيقًا (69) وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا ۗ إِنَّ اللَّهَ كَانَ عَلَىٰ كُلِّ شَيْءٍ حَسِيبًا (86) يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ وَلَوْ عَلَىٰ أَنفُسِكُمْ أَوِ الْوَالِدَيْنِ وَالْأَقْرَبِينَ ۚ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَاللَّهُ أَوْلَىٰ بِهِمَا ۖ فَلَا تَتَّبِعُوا الْهَوَىٰ أَن تَعْدِلُوا ۚ وَإِن تَلْوُوا أَوْ تُعْرِضُوا فَإِنَّ اللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا (135) يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُم بُرْهَانٌ مِّن رَّبِّكُمْ وَأَنزَلْنَا إِلَيْكُمْ نُورًا مُّبِينًا (174)",
