                    tafsirAlAmthal = "في «تفسير الأمثل في تفسير كتاب الله المنزل»: تفتتح سورة النساء بهذا النداء الإنساني الشامل؛ لترسيخ وحدة الأصل البشري وإلغاء كل فوارق الطبقية والعنصرية والاستعلاء الذكوري على المرأة؛ فالجميع خُلقوا من نفس واحدة. كما تقرن الآية تقوى الله بحرمة (الأرحام)، مما يوضح أن صلة الرحم والتكافل الاجتماعي جزء لا يتجزأ من الإيمان والتقوى.",
