            revelationType = "مدنية",
            hasBasmalah = true,
            educationalNotes = "سورة مدنية جليلة تُعرف بسورة العقود والمائدة والمنقذة، نزلت في أواخر العهد النبوي وتضمنت تشريعات ختامية حاسمة. افتتحت بالأمر الإلهي القاطع بالوفاء بالعقود والعهود، واشتملت على آية إكمال الدين والنعمة (الآية 3)، وأحكام الطهارة والوضوء والتيمم (الآية 6)، وآية الولاية وخاتم التصدق (الآية 55)، وآية التبليغ وأمر الغدير (الآية 67)، وقصة ابني آدم وقيمة النفس البشرية، وحوار النبي عيسى بن مريم عليه السلام في شأن المائدة والتوحيد الخالص. غنية بأحكام التجويد المتقنة: المد المتصل والمنفصل، إدغام بغنة وبغير غنة، إخفاء حقيقي، قلقلة، وتفخيم وترقيق اللامات والراءات.",
            majmaAlBayanOverview = "في «مجمع البيان في تفسير القرآن» لأمين الإسلام الشيخ أبي علي الفضل بن الحسن الطبرسي: سورة المائدة مدنية بالإجماع، وهي مئة وعشرون آية في عدّ البصريين ومئة واثنتان وعشرون في عدّ الكوفيين. عن أمير المؤمنين علي بن أبي طالب عليه السلام: «كان القرآن ينسخ بعضه بعضاً وإنما يؤخذ من أمر رسول الله ﷺ بآخره فالآخر، وكانت سورة المائدة من آخر ما نزل عليه فنسخت ما قبلها ولم ينسخها شيء». وعن النبي ﷺ: «من قرأ سورة المائدة أُعطي من الأجر بعدد كل يهودي ونصراني يتنفس في دار الدنيا عشر حسنات ومُحي عنه عشر سيئات ورُفع له عشر درجات». وبيّن الطبرسي أن افتتاحها بالوفاء بالعقود يشمل كل عهد عقده الله على عباده في التوحيد والفرائض والحلال والحرام، وما يعقده الناس بينهم من أمانات وبيوع وعهود، وأن آياتها تضم أعظم ركائز الإيمان والتشريع الإلهي كآية إكمال الدين، وآية الولاية {إِنَّمَا وَلِيُّكُمُ اللَّهُ وَرَسُولُهُ وَالَّذِينَ آمَنُوا}، وآية التبليغ الحاسم {بَلِّغْ مَا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ}، ومائدة عيسى عليه السلام التي أنزلها الله آية وبرهاناً.",
            alMizanOverview = "في «الميزان في تفسير القرآن» للعلامة الطباطبائي: سورة المائدة آخر ما نزل، نزلت بالوفاء بالعقود، وفيها إعلان إكمال الدين وإتمام النعمة يوم غدير خم (الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ)، وآية الولاية (إِنَّمَا وَلِيُّكُمُ اللَّهُ وَرَسُولُهُ وَالَّذِينَ آمَنُوا)، وآية التبليغ الحاسمة، وأحكام الطهارة ومائدة عيسى عليه السلام.",
            fullText = "يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ ۚ أُحِلَّتْ لَكُم بَهِيمَةُ الْأَنْعَامِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّي الصَّيْدِ وَأَنتُمْ حُرُمٌ ۗ إِنَّ اللَّهَ يَحْكُمُ مَا يُرِيدُ (1) يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُحِلُّوا شَعَائِرَ اللَّهِ وَلَا الشَّهْرَ الْحَرَامَ وَلَا الْهَدْيَ وَلَا الْقَلَائِدَ وَلَا آمِّينَ الْبَيْتَ الْحَرَامَ يَبْتَغُونَ فَضْلًا مِّن رَّبِّهِمْ وَرِضْوَانًا ۚ ... وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَىٰ ۖ وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ ۚ وَاتَّقُوا اللَّهَ ۖ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ (2) حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ ... الْيَوْمَ يَئِسَ الَّذِينَ كَفَرُوا مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ ۚ الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا ۚ ... (3) يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ ۚ ... (6) إِنَّمَا وَلِيُّكُمُ اللَّهُ وَرَسُولُهُ وَالَّذِينَ آمَنُوا الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُمْ رَاكِعُونَ (55) يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ۖ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ ۚ وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ ۗ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ (67) قَالَ عِيسَى ابْنُ مَرْيَمَ اللَّهُمَّ رَبَّنَا أَنزِلْ عَلَيْنَا مَائِدَةً مِّنَ السَّمَاءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَآخِرِنَا وَآيَةً مِّنكَ ۖ وَارْزُقْنَا وَأَنتَ خَيْرُ الرَّازِقِينَ (114)",
