                    ),
                    tafsir = "يا أيها الذين صدقوا الله ورسوله وعملوا بشرعه، أتموا العهود المؤكدة التي بينكم وبين ربكم من الطاعات، والتي بينكم وبين الناس من العقود والمعاملات. قد أحل الله لكم بهيمة الأنعام إلا ما يقرأ عليكم تحريمه في كتابه، محظوراً عليكم صيد البر وأنتم محرمون بحج أو عمرة، إن الله يقضي في خلقه ما يشاء بحكمته وعدله.",
