                    tafsirAlAmthal = "في «تفسير الأمثل»: سميت سورة المائدة بهذا الاسم لذكر هذه المعجزة السماوية العظيمة التي طلبها الحواريون ليطمئنوا وليكون لهم عيداً. ويبيّن الإمام الباقر عليه السلام في تفسير هذه الآية: أن المائدة نزلت مشحونة بأنواع الأطعمة الطيبة وثمار الجنة، فكانت شفاءً لكل مريض وأماناً للمحتاجين، وبرهاناً مادياً قاطعاً على صدق نبوة السيد المسيح عليه السلام.",
